import { useEffect, useMemo, useState } from "react";
import { useLocation } from "wouter";
import { ArrowLeft, Building2, ChevronRight, CircleAlert, Clock3, ExternalLink, Filter, ImageIcon, MapPin, Pencil, Plus, Power, Search, Trash2, Upload } from "lucide-react";
import { toast } from "sonner";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { trpc } from "@/lib/trpc";
import { useEffectivePermissions } from "@/hooks/useEffectivePermissions";
import { CoordinatesField, StoreHoursField } from "@/components/StoreLocationFields";
import { STORE_WEEKDAYS, formatStoreHours, parseStoreHours } from "@shared/storeHours";

type RegistryRecord = Record<string, unknown> & { id: number; active?: boolean; name?: string; displayName?: string; phone?: string | null; email?: string | null };
type EntityConfig = { singular: string; plural: string; collection: string; kind: string; description: string; icon: typeof Building2 };
type SupervisorStoreLink = { commercialSupervisorId: number; storeId: number };

const entities: Record<string, EntityConfig> = {
  empresas: { singular: "Empresa", plural: "Empresas", collection: "providers", kind: "provider", description: "Dados de faturamento, cobertura territorial, lojas, fornecedores e operações associadas.", icon: Building2 },
  regionais: { singular: "Regional", plural: "Regionais", collection: "regionals", kind: "regional", description: "Estrutura territorial, empresa responsável, cidades, lojas e operações associadas.", icon: MapPin },
  cidades: { singular: "Cidade", plural: "Cidades", collection: "cities", kind: "city", description: "Localização, dados de território, lojas, fornecedores e referências operacionais.", icon: MapPin },
  lojas: { singular: "Loja", plural: "Lojas", collection: "stores", kind: "store", description: "Unidades de atendimento e respectivas referências territoriais.", icon: Building2 },
  fornecedores: { singular: "Fornecedor", plural: "Fornecedores", collection: "suppliers", kind: "supplier", description: "Contatos, cobertura, serviços contratáveis e condições comerciais.", icon: Building2 },
  parceiros: { singular: "Parceiro", plural: "Parceiros", collection: "partners", kind: "partner", description: "Contatos, contratos e condições de parceria.", icon: Building2 },
  supervisores: { singular: "Supervisor comercial", plural: "Supervisores comerciais", collection: "commercialSupervisors", kind: "supervisor", description: "Pessoas responsáveis e lojas sob supervisão comercial.", icon: Building2 },
  servicos: { singular: "Serviço", plural: "Serviços", collection: "serviceTypes", kind: "service", description: "Serviços disponíveis para contratação e configuração da operação.", icon: Building2 },
  "tipos-de-produto": { singular: "Tipo de produto", plural: "Tipos de produto", collection: "productTypes", kind: "product", description: "Categorias de produtos para composição das ofertas de fornecedores.", icon: Building2 },
  "tipos-de-midia": { singular: "Tipo de mídia", plural: "Tipos de mídia", collection: "mediaTypes", kind: "media", description: "Canais e formatos para planejamento de mídia.", icon: Building2 },
  "tipos-de-acao": { singular: "Tipo de ação", plural: "Tipos de ação", collection: "actionTypes", kind: "action", description: "Classificações usadas no planejamento de ações.", icon: Building2 },
  "tipos-de-evento": { singular: "Tipo de evento", plural: "Tipos de evento", collection: "eventTypes", kind: "event", description: "Classificações usadas no planejamento de eventos.", icon: Building2 },
  "tipos-de-campanha": { singular: "Atuação", plural: "Atuações", collection: "campaignTypes", kind: "campaign", description: "Classificações reutilizáveis, como Comercial, Fidelização e outras estratégias.", icon: Building2 },
  "setores-de-campanha": { singular: "Setor", plural: "Setores", collection: "campaignSectors", kind: "campaign_sector", description: "Segmentos reutilizáveis, como B2C, B2B, PME e demais públicos.", icon: Building2 },
  "categorias-financeiras": { singular: "Categoria financeira", plural: "Categorias financeiras", collection: "financialCategories", kind: "financial_category", description: "Classificações de estimativas, verbas e controles financeiros.", icon: Building2 },
};

const registryPaths: Record<string, string> = { provider: "empresas", regional: "regionais", city: "cidades", store: "lojas", supplier: "fornecedores", partner: "parceiros", supervisor: "supervisores", service: "servicos", product: "tipos-de-produto", media: "tipos-de-midia", action: "tipos-de-acao", event: "tipos-de-evento", campaign: "tipos-de-campanha", campaign_sector: "setores-de-campanha", financial_category: "categorias-financeiras" };
const registryGroups: Record<string, string> = { provider: "territorio", regional: "territorio", city: "territorio", store: "territorio", supplier: "parceiros", partner: "parceiros", supervisor: "parceiros", service: "parceiros", product: "parceiros", media: "categorias", action: "categorias", event: "categorias", campaign: "operacao", campaign_sector: "operacao", financial_category: "financeiro" };

function recordName(record: RegistryRecord) { return String(record.displayName ?? record.name ?? "Sem identificação"); }
function digits(value?: string | null) { return String(value ?? "").replace(/\D/g, ""); }
function whatsappUrl(phone?: string | null) { const number = digits(phone); return number.length >= 10 ? `https://wa.me/55${number.replace(/^55/, "")}` : null; }

export default function RegistryEntityWorkspace() {
  const [location, setLocation] = useLocation();
  const cleanPath = location.split("?")[0];
  const [, , slug = "", rawId] = cleanPath.split("/");
  const entity = entities[slug];
  const entityId = rawId ? Number(rawId) : null;
  const { can } = useEffectivePermissions();
  const utils = trpc.useUtils();
  const overview = trpc.settings.overview.useQuery(undefined, { staleTime: 20_000 });
  const [editing, setEditing] = useState(false);
  const [form, setForm] = useState<Record<string, string>>({});
  const [search, setSearch] = useState("");
  const [activeFilter, setActiveFilter] = useState<"all" | "active" | "inactive">("all");
  const [filtersOpen, setFiltersOpen] = useState(false);
  const [companyFilter, setCompanyFilter] = useState("");
  const [regionalFilter, setRegionalFilter] = useState("");
  const [cityFilter, setCityFilter] = useState("");
  const [expandedRelation, setExpandedRelation] = useState<string | null>(null);
  const updateProvider = trpc.settings.updateProvider.useMutation({ onSuccess: () => { toast.success("Empresa atualizada."); utils.settings.overview.invalidate(); setEditing(false); } });
  const updateRegional = trpc.settings.updateRegional.useMutation({ onSuccess: () => { toast.success("Regional atualizada."); utils.settings.overview.invalidate(); setEditing(false); } });
  const updateCity = trpc.settings.updateCity.useMutation({ onSuccess: () => { toast.success("Cidade atualizada."); utils.settings.overview.invalidate(); setEditing(false); } });
  const updateSupplier = trpc.settings.updateSupplier.useMutation({ onSuccess: () => { toast.success("Fornecedor atualizado."); utils.settings.overview.invalidate(); setEditing(false); } });
  const updateStore = trpc.settings.updateStore.useMutation({ onSuccess: () => { toast.success("Loja atualizada."); utils.settings.overview.invalidate(); setEditing(false); } });
  const updatePartner = trpc.settings.updatePartner.useMutation({ onSuccess: () => { toast.success("Parceiro atualizado."); utils.settings.overview.invalidate(); setEditing(false); } });
  const updateSupervisor = trpc.settings.updateCommercialSupervisor.useMutation({ onSuccess: () => { toast.success("Supervisor atualizado."); utils.settings.overview.invalidate(); setEditing(false); } });
  const updateType = trpc.settings.updateType.useMutation({ onSuccess: () => { toast.success("Tipo atualizado."); utils.settings.overview.invalidate(); setEditing(false); } });
  const updateFinancialCategory = trpc.settings.updateFinancialCategory.useMutation({ onSuccess: () => { toast.success("Categoria atualizada."); utils.settings.overview.invalidate(); setEditing(false); } });
  const uploadProviderLogo = trpc.settings.uploadProviderLogo.useMutation({ onSuccess: () => { toast.success("Logotipo atualizado."); utils.settings.overview.invalidate(); }, onError: error => toast.error(error.message) });
  const uploadProviderCnpjCard = trpc.settings.uploadProviderCnpjCard.useMutation({ onSuccess: () => { toast.success("Cartão CNPJ atualizado."); utils.settings.overview.invalidate(); }, onError: error => toast.error(error.message) });
  const uploadProviderBrandManual = trpc.settings.uploadProviderBrandManual.useMutation({ onSuccess: () => { toast.success("Manual da marca atualizado."); utils.settings.overview.invalidate(); }, onError: error => toast.error(error.message) });
  const uploadStorePhoto = trpc.settings.uploadStorePhoto.useMutation({ onSuccess: () => { toast.success("Foto da loja atualizada."); utils.settings.overview.invalidate(); }, onError: error => toast.error(error.message) });
  const uploadSupplierPhoto = trpc.settings.uploadSupplierPhoto.useMutation({ onSuccess: () => { toast.success("Foto do fornecedor atualizada."); utils.settings.overview.invalidate(); }, onError: error => toast.error(error.message) });
  const setSupervisorStores = trpc.settings.setCommercialSupervisorStores.useMutation({ onSuccess: () => { toast.success("Cobertura de supervisão atualizada."); utils.settings.overview.invalidate(); }, onError: error => toast.error(error.message) });
  const setActive = trpc.settings.setRegistryActive.useMutation({ onSuccess: (_result, variables) => { toast.success(variables.active ? "Cadastro ativado." : "Cadastro inativado."); utils.settings.overview.invalidate(); }, onError: error => toast.error(error.message) });
  const remove = trpc.settings.deleteRegistry.useMutation({ onSuccess: () => { toast.success("Cadastro excluído com segurança."); utils.settings.overview.invalidate(); setLocation(`/cadastros/${slug}`); }, onError: error => toast.error(error.message) });

  const rows = useMemo(() => (((overview.data as Record<string, unknown> | undefined)?.[entity?.collection ?? ""] ?? []) as RegistryRecord[]), [overview.data, entity?.collection]);
  const selected = entityId ? rows.find(item => item.id === entityId) : undefined;
  const providers = (((overview.data as Record<string, unknown> | undefined)?.providers ?? []) as RegistryRecord[]);
  const regionals = (((overview.data as Record<string, unknown> | undefined)?.regionals ?? []) as RegistryRecord[]);
  const cities = (((overview.data as Record<string, unknown> | undefined)?.cities ?? []) as RegistryRecord[]);
  const stores = (((overview.data as Record<string, unknown> | undefined)?.stores ?? []) as RegistryRecord[]);
  const suppliers = (((overview.data as Record<string, unknown> | undefined)?.suppliers ?? []) as RegistryRecord[]);
  const supervisors = (((overview.data as Record<string, unknown> | undefined)?.commercialSupervisors ?? []) as RegistryRecord[]);
  const supervisorStoreLinks = (((overview.data as Record<string, unknown> | undefined)?.commercialSupervisorStores ?? []) as SupervisorStoreLink[]);
  const serviceTypes = (((overview.data as Record<string, unknown> | undefined)?.serviceTypes ?? []) as RegistryRecord[]);
  const mediaTypes = (((overview.data as Record<string, unknown> | undefined)?.mediaTypes ?? []) as RegistryRecord[]);
  const supplierOfferings = (((overview.data as Record<string, unknown> | undefined)?.supplierOfferings ?? []) as RegistryRecord[]);
  const operationalFootprint = (((overview.data as Record<string, unknown> | undefined)?.operationalFootprint ?? {}) as SupplierOperationalFootprint);
  const supplierCoverage = trpc.settings.supplierCoverage.useQuery(undefined, { enabled: entity?.kind === "supplier" && Boolean(selected) });
  const filteredRows = rows.filter(row => {
    const text = `${recordName(row)} ${String(row.email ?? "")} ${String(row.code ?? "")}`.toLocaleLowerCase("pt-BR");
    const regionalId = Number(row.regionalId ?? (row.cityId ? cities.find(city => city.id === Number(row.cityId))?.regionalId : 0));
    return (activeFilter === "all" || (activeFilter === "active" ? row.active !== false : row.active === false))
      && text.includes(search.toLocaleLowerCase("pt-BR"))
      && (!companyFilter || Number(row.providerId ?? row.headquartersCityId) === Number(companyFilter))
      && (!regionalFilter || regionalId === Number(regionalFilter))
      && (!cityFilter || Number(row.cityId ?? row.headquartersCityId) === Number(cityFilter));
  });
  const clearFilters = () => { setSearch(""); setActiveFilter("all"); setCompanyFilter(""); setRegionalFilter(""); setCityFilter(""); };

  useEffect(() => {
    if (!selected) return;
    setForm({
      name: recordName(selected), providerRecordId: String(selected.id),
      code: String(selected.code ?? ""), state: String(selected.state ?? "MG"), providerId: selected.providerId ? String(selected.providerId) : "",
      regionalId: selected.regionalId ? String(selected.regionalId) : "", legalName: String(selected.legalName ?? ""), billingCnpj: String(selected.billingCnpj ?? ""),
      contactName: String(selected.contactName ?? ""), phone: String(selected.phone ?? ""), email: String(selected.email ?? ""), website: String(selected.website ?? ""), address: String(selected.address ?? ""), headquartersCityId: selected.headquartersCityId ? String(selected.headquartersCityId) : "", brandColors: Array.isArray(selected.brandColors) ? selected.brandColors.join(", ") : "",
      ibgeCode: String(selected.ibgeCode ?? ""), zipCode: String(selected.zipCode ?? ""), latitude: String(selected.latitude ?? ""), longitude: String(selected.longitude ?? ""), locationNotes: String(selected.locationNotes ?? ""), referencePoint: String(selected.referencePoint ?? ""), openingHours: String(selected.openingHours ?? ""), document: String(selected.document ?? ""), cityId: selected.cityId ? String(selected.cityId) : "", partnershipType: String(selected.partnershipType ?? "paid"), paymentMethod: String(selected.paymentMethod ?? ""), paymentRecurrence: String(selected.paymentRecurrence ?? ""), hasContract: selected.hasContract ? "yes" : "no", mainService: String(selected.mainService ?? ""), description: String(selected.description ?? ""), operationCategory: String(selected.operationCategory ?? "graphics"), parentMediaTypeId: selected.parentMediaTypeId ? String(selected.parentMediaTypeId) : "",
    });
  }, [selected]);

  if (!entity) return <div className="rounded-2xl border border-border bg-card p-8 text-center"><CircleAlert className="mx-auto h-7 w-7 text-muted-foreground" /><h1 className="mt-3 font-display text-xl font-semibold">Cadastro não encontrado</h1><Button className="mt-5" variant="outline" onClick={() => setLocation("/cadastros/territorio")}>Voltar aos Cadastros</Button></div>;
  if (overview.isLoading) return <div className="grid min-h-64 place-items-center text-sm text-muted-foreground">Carregando {entity.plural.toLowerCase()}…</div>;
  const Icon = entity.icon;
  const canWrite = can("settings.write");
  const isTerritorial = ["regional", "city", "store"].includes(entity.kind);
  const allRelationCards = selected ? getRelations(entity.kind, selected, { providers, regionals, cities, stores, suppliers }) : [];
  const relationCards = isTerritorial ? [] : allRelationCards;
  const storeSupervisors = selected && entity.kind === "store" ? supervisors.filter(supervisor => supervisorStoreLinks.some(link => link.storeId === selected.id && link.commercialSupervisorId === supervisor.id)) : [];
  const toggleStoreSupervisor = (supervisorId: number) => {
    if (!selected || entity.kind !== "store") return;
    const currentStoreIds = supervisorStoreLinks.filter(link => link.commercialSupervisorId === supervisorId).map(link => link.storeId);
    const storeIds = currentStoreIds.includes(selected.id) ? currentStoreIds.filter(id => id !== selected.id) : [...currentStoreIds, selected.id];
    setSupervisorStores.mutate({ commercialSupervisorId: supervisorId, storeIds });
  };
  function TerritorialDetailsLayout() {
    if (!selected) return null;
    const parent = entity.kind === "regional" ? providers.find(provider => provider.id === selected.providerId) : entity.kind === "city" ? regionals.find(regional => regional.id === selected.regionalId) : cities.find(city => city.id === selected.cityId);
    const parentLabel = entity.kind === "regional" ? "Empresa responsável" : entity.kind === "city" ? "Regional vinculada" : "Cidade vinculada";
    const photoUpload = (file: File) => { const reader = new FileReader(); reader.onload = () => { const base64 = String(reader.result).split(",")[1]; if (base64) uploadStorePhoto.mutate({ storeId: selected.id, originalName: file.name, mimeType: file.type as "image/jpeg" | "image/png" | "image/webp", dataBase64: base64 }); }; reader.readAsDataURL(file); };
    const storeHours = entity.kind === "store" ? parseStoreHours(String(selected.openingHours ?? "")) : null;
    return <section className="grid gap-5 xl:grid-cols-[minmax(0,1.25fr)_minmax(320px,.75fr)]"><div className="space-y-5"><DetailOverview entity={entity} record={selected} />{storeHours ? <section className="rounded-[10px] border border-border bg-card p-5 shadow-sm"><div className="flex items-center justify-between gap-3"><div><h2 className="font-display text-lg font-semibold text-foreground">Horário de funcionamento</h2><p className="text-sm text-muted-foreground">Dias e horários cadastrados para esta unidade.</p></div><Clock3 className="h-5 w-5 text-primary" /></div><div className="mt-4 grid gap-2 sm:grid-cols-2">{STORE_WEEKDAYS.map(({ key, label }) => { const day = storeHours[key]; return <div key={key} className={`flex items-center justify-between rounded-lg border px-3 py-2 ${day.enabled ? "border-primary/20 bg-primary/5" : "border-border bg-muted/20"}`}><span className="text-sm font-medium text-foreground">{label}</span><span className="text-sm text-muted-foreground">{day.enabled ? `${day.open || "--:--"} – ${day.close || "--:--"}` : "Fechado"}</span></div>; })}</div></section> : null}{allRelationCards.length ? <section className="rounded-[10px] border border-border bg-card p-5 shadow-sm"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-[10px] bg-primary/10 text-primary"><MapPin className="h-5 w-5" /></span><div><h2 className="font-display text-xl font-semibold text-foreground">Vínculos e cobertura</h2><p className="text-sm text-muted-foreground">Consulte os registros relacionados a esta {entity.singular.toLowerCase()}.</p></div></div><div className="mt-5 grid gap-3 sm:grid-cols-2">{allRelationCards.map(card => <button key={card.label} onClick={() => setExpandedRelation(current => current === card.label ? null : card.label)} className={`rounded-[10px] border p-4 text-left transition hover:border-primary/40 ${expandedRelation === card.label ? "border-primary bg-primary/5 ring-2 ring-primary/10" : "border-border bg-background"}`}><p className="text-2xl font-semibold text-primary">{card.count}</p><p className="mt-1 text-sm font-semibold text-foreground">{card.label}</p><p className="mt-1 text-xs text-muted-foreground">{card.description}</p></button>)}</div>{expandedRelation ? <ExpandedRelationPanel label={expandedRelation} rows={allRelationCards.find(card => card.label === expandedRelation)?.items ?? []} destination={allRelationCards.find(card => card.label === expandedRelation)?.path ?? "/cadastros/territorio"} onOpen={(id: number) => { const card = allRelationCards.find(item => item.label === expandedRelation); if (card) setLocation(`${card.path}/${id}`); }} onViewAll={() => { const card = allRelationCards.find(item => item.label === expandedRelation); if (card) setLocation(card.path); }} /> : null}</section> : null}</div><aside className="space-y-5"><Card><CardContent className="p-5"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-[10px] bg-primary/10 text-primary"><MapPin className="h-5 w-5" /></span><div><p className="text-xs font-semibold uppercase tracking-[0.14em] text-primary">Estrutura territorial</p><h2 className="mt-1 font-display text-xl font-semibold text-foreground">Contexto do cadastro</h2></div></div><div className="mt-5 space-y-3"><div className="rounded-[10px] border border-border bg-muted/30 p-3"><p className="text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">{parentLabel}</p><p className="mt-1 text-sm font-semibold text-foreground">{parent ? recordName(parent) : "Não informado"}</p></div><div className="rounded-[10px] border border-border bg-muted/30 p-3"><p className="text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">Status</p><p className="mt-1 text-sm font-semibold text-foreground">{selected.active === false ? "Inativo" : "Ativo"}</p></div>{selected.latitude && selected.longitude ? <div className="rounded-[10px] border border-border bg-muted/30 p-3"><p className="text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">Coordenadas</p><p className="mt-1 text-sm font-semibold text-foreground">{String(selected.latitude)}, {String(selected.longitude)}</p></div> : null}</div></CardContent></Card>{entity.kind === "store" ? <StorePhotoPanel store={selected} canWrite={canWrite} isPending={uploadStorePhoto.isPending} onUpload={photoUpload} /> : null}{entity.kind === "store" ? <StoreSupervisorsPanel supervisors={supervisors} linkedSupervisors={storeSupervisors} canWrite={canWrite} isPending={setSupervisorStores.isPending} onToggle={toggleStoreSupervisor} /> : null}</aside></section>;
  }
  const save = () => {
    if (!selected) return;
    if (entity.kind === "provider") return updateProvider.mutate({ id: selected.id, name: form.name.trim(), legalName: form.legalName.trim() || undefined, billingCnpj: form.billingCnpj.trim() || undefined, contactName: form.contactName.trim() || undefined, phone: form.phone.trim() || undefined, email: form.email.trim() || undefined, website: form.website.trim() || undefined, address: form.address.trim() || undefined, headquartersCityId: form.headquartersCityId ? Number(form.headquartersCityId) : null, brandColors: form.brandColors.split(",").map(color => color.trim()).filter(Boolean) });
    if (entity.kind === "regional") return updateRegional.mutate({ id: selected.id, name: form.name.trim(), code: form.code.trim().toUpperCase(), providerId: form.providerId ? Number(form.providerId) : null });
    if (entity.kind === "city") return updateCity.mutate({ id: selected.id, name: form.name.trim(), state: form.state.trim().toUpperCase(), regionalId: Number(form.regionalId), ibgeCode: form.ibgeCode.trim() || undefined, address: form.address.trim() || undefined, zipCode: form.zipCode.trim() || undefined, latitude: form.latitude ? Number(form.latitude) : undefined, longitude: form.longitude ? Number(form.longitude) : undefined, locationNotes: form.locationNotes.trim() || undefined });
    if (entity.kind === "store") return updateStore.mutate({ id: selected.id, cityId: Number(form.cityId), name: form.name.trim(), code: form.code.trim().toUpperCase(), address: form.address.trim() || undefined, referencePoint: form.referencePoint.trim() || undefined, zipCode: form.zipCode.trim() || undefined, phone: form.phone.trim() || undefined, email: form.email.trim() || undefined, openingHours: form.openingHours.trim() || undefined, latitude: form.latitude ? Number(form.latitude) : null, longitude: form.longitude ? Number(form.longitude) : null, active: selected.active !== false });
    if (entity.kind === "supplier") return updateSupplier.mutate({ id: selected.id, providerId: form.providerId ? Number(form.providerId) : null, cityId: form.cityId ? Number(form.cityId) : null, displayName: form.name.trim(), legalName: form.legalName.trim() || undefined, document: form.document.trim(), contactName: form.contactName.trim() || undefined, phone: form.phone.trim(), email: form.email.trim(), mainService: form.mainService.trim() || undefined, partnershipType: form.partnershipType as "paid" | "barter" | "mixed", paymentMethod: form.paymentMethod.trim() || undefined, paymentRecurrence: form.paymentRecurrence.trim() || undefined, hasContract: form.hasContract === "yes" });
    if (entity.kind === "partner") return updatePartner.mutate({ id: selected.id, cityId: form.cityId ? Number(form.cityId) : null, name: form.name.trim(), email: form.email.trim() || undefined, phone: form.phone.trim() || undefined, partnershipType: form.partnershipType as "paid" | "barter" | "mixed", paymentMethod: form.paymentMethod.trim() || undefined, paymentRecurrence: form.paymentRecurrence.trim() || undefined, hasContract: form.hasContract === "yes" });
    if (entity.kind === "supervisor") return updateSupervisor.mutate({ id: selected.id, name: form.name.trim(), email: form.email.trim() || undefined, phone: form.phone.trim() || undefined });
    if (["service", "media", "action", "event", "campaign", "campaign_sector"].includes(entity.kind)) return updateType.mutate({ id: selected.id, kind: entity.kind as "service" | "media" | "action" | "event" | "campaign" | "campaign_sector", name: form.name.trim(), ...(entity.kind === "media" ? { operationCategory: form.operationCategory as "graphics" | "audio_video" | "leafleting" | "sound_car" | "influencers", parentMediaTypeId: form.parentMediaTypeId ? Number(form.parentMediaTypeId) : null } : {}) });
    if (entity.kind === "financial_category") return updateFinancialCategory.mutate({ id: selected.id, name: form.name.trim(), description: form.description.trim() || undefined });
  };

  return <div className="mx-auto max-w-6xl space-y-6">
    <div className="flex flex-col gap-4 border-b border-border pb-6 sm:flex-row sm:items-start sm:justify-between">
      <div className="flex gap-4"><span className="grid h-12 w-12 shrink-0 place-items-center rounded-2xl bg-primary text-primary-foreground shadow-sm"><Icon className="h-5 w-5" /></span><div><nav className="mb-2 flex items-center gap-1 text-xs text-muted-foreground"><button onClick={() => setLocation(`/cadastros/${registryGroups[entity.kind] ?? "territorio"}`)} className="hover:text-primary">Cadastros</button><ChevronRight className="h-3 w-3" /><button onClick={() => setLocation(`/cadastros/${slug}`)} className="hover:text-primary">{entity.plural}</button>{selected ? <><ChevronRight className="h-3 w-3" /><span className="max-w-52 truncate text-foreground">{recordName(selected)}</span></> : null}</nav><h1 className="font-display text-3xl font-semibold tracking-tight text-foreground">{selected ? recordName(selected) : entity.plural}</h1><p className="mt-1 max-w-3xl text-sm leading-6 text-muted-foreground">{entity.description}</p></div></div>
      {!selected && canWrite ? <Button onClick={() => setLocation(`/cadastros/${registryGroups[entity.kind] ?? "territorio"}?novo=${slug}`)} className="bg-primary text-primary-foreground"><Plus className="mr-2 h-4 w-4" />Adicionar {entity.singular.toLowerCase()}</Button> : null}
    </div>
    {!selected ? <section><div className="mb-4 flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-border bg-card p-4"><div className="relative min-w-0 flex-1 max-w-xl"><Search className="pointer-events-none absolute left-3 top-3 h-4 w-4 text-muted-foreground" /><Input value={search} onChange={event => setSearch(event.target.value)} placeholder={`Pesquisar ${entity.plural.toLowerCase()}…`} className="pl-9" aria-label="Pesquisar" /></div><p className="text-sm font-medium text-foreground">{filteredRows.length} de {rows.length} cadastros</p><Button type="button" variant="outline" onClick={() => setFiltersOpen(value => !value)} aria-expanded={filtersOpen}><Filter className="mr-2 h-4 w-4" />Filtros</Button></div>{filtersOpen ? <div className="mb-4 space-y-4 rounded-2xl border border-border bg-card p-4"><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4"><select aria-label="Status" value={activeFilter} onChange={event => setActiveFilter(event.target.value as typeof activeFilter)} className="h-10 rounded-md border border-input bg-background px-3 text-sm"><option value="all">Todos os status</option><option value="active">Ativos</option><option value="inactive">Inativos</option></select><select aria-label="Empresa" value={companyFilter} onChange={event => setCompanyFilter(event.target.value)} className="h-10 rounded-md border border-input bg-background px-3 text-sm"><option value="">Todas as empresas</option>{providers.map(provider => <option key={provider.id} value={provider.id}>{recordName(provider)}</option>)}</select><select aria-label="Regional" value={regionalFilter} onChange={event => setRegionalFilter(event.target.value)} className="h-10 rounded-md border border-input bg-background px-3 text-sm"><option value="">Todas as regionais</option>{regionals.map(regional => <option key={regional.id} value={regional.id}>{recordName(regional)}</option>)}</select><select aria-label="Cidade" value={cityFilter} onChange={event => setCityFilter(event.target.value)} className="h-10 rounded-md border border-input bg-background px-3 text-sm"><option value="">Todas as cidades</option>{cities.map(city => <option key={city.id} value={city.id}>{recordName(city)}{city.state ? `/${city.state}` : ""}</option>)}</select></div><div className="flex justify-end"><Button type="button" variant="ghost" onClick={clearFilters}>Redefinir filtros</Button></div></div> : null}<div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{filteredRows.map(row => <button key={row.id} onClick={() => setLocation(`/cadastros/${slug}/${row.id}`)} className="rounded-2xl border border-border bg-card p-5 text-left shadow-sm transition hover:border-primary/40 hover:shadow-md"><div className="flex items-start justify-between gap-3">{entity.kind === "store" && typeof row.photoUrl === "string" && row.photoUrl ? <img src={row.photoUrl} alt={`Foto de ${recordName(row)}`} className="h-10 w-10 shrink-0 rounded-xl object-cover" /> : <span className="grid h-10 w-10 place-items-center rounded-xl bg-primary/10 text-primary"><Icon className="h-4 w-4" /></span>}<Badge variant="outline" className={row.active === false ? "border-border text-muted-foreground" : "border-primary/30 bg-primary/10 text-primary"}>{row.active === false ? "Inativo" : "Ativo"}</Badge></div><h2 className="mt-5 font-display text-lg font-semibold text-foreground">{recordName(row)}</h2><p className="mt-1 min-h-5 text-xs text-muted-foreground">{summary(entity.kind, row, { providers, regionals, cities })}</p><span className="mt-5 inline-flex items-center text-xs font-semibold text-primary">Ver informações <ChevronRight className="ml-1 h-3.5 w-3.5" /></span></button>)}{filteredRows.length === 0 ? <Card className="sm:col-span-2 xl:col-span-3"><CardContent className="p-8 text-center text-sm text-muted-foreground">Nenhum cadastro encontrado para a busca ou filtro selecionado.</CardContent></Card> : null}</div></section> : <section className="space-y-5">
      <div className="flex flex-wrap gap-3"><Button variant="outline" onClick={() => setLocation(`/cadastros/${slug}`)}><ArrowLeft className="mr-2 h-4 w-4" />Voltar à lista</Button>{canWrite ? <Button onClick={() => setEditing(value => !value)} className="bg-primary text-primary-foreground"><Pencil className="mr-2 h-4 w-4" />{editing ? "Cancelar edição" : "Editar informações"}</Button> : null}{canWrite ? <Button variant="outline" disabled={setActive.isPending} onClick={() => setActive.mutate({ kind: entity.kind as never, id: selected.id, active: selected.active === false })}><Power className="mr-2 h-4 w-4" />{selected.active === false ? "Ativar" : "Inativar"}</Button> : null}{canWrite ? <Button variant="outline" className="border-destructive/40 text-destructive hover:bg-destructive/10" onClick={() => { const deletionMessage = entity.kind === "provider" ? `Excluir ${entity.singular.toLowerCase()}? Regionais e fornecedores vinculados serão desvinculados da empresa, preservando os demais dados.` : `Excluir ${entity.singular.toLowerCase()}? A exclusão só será concluída se não houver vínculos operacionais dependentes.`; if (window.confirm(deletionMessage)) remove.mutate({ kind: entity.kind as never, id: selected.id }); }}><Trash2 className="mr-2 h-4 w-4" />Excluir</Button> : null}</div>
      {editing ? <RegistryEditor kind={entity.kind} form={form} setForm={setForm} providers={providers} regionals={regionals} cities={cities} mediaTypes={mediaTypes} serviceTypes={serviceTypes} onSave={save} saving={updateProvider.isPending || updateRegional.isPending || updateCity.isPending || updateStore.isPending || updateSupplier.isPending || updatePartner.isPending || updateSupervisor.isPending || updateType.isPending || updateFinancialCategory.isPending} /> : isTerritorial ? <TerritorialDetailsLayout /> : <DetailOverview entity={entity} record={selected} />}
      {entity.kind === "provider" ? <><ProviderLogoPanel provider={selected} canWrite={canWrite} isPending={uploadProviderLogo.isPending} onUpload={(file: File) => { const reader = new FileReader(); reader.onload = () => { const base64 = String(reader.result).split(",")[1]; if (base64) uploadProviderLogo.mutate({ providerId: selected.id, originalName: file.name, mimeType: file.type as "image/jpeg" | "image/png" | "image/webp", dataBase64: base64 }); }; reader.readAsDataURL(file); }} /><div className="grid gap-4 md:grid-cols-2"><ProviderDocumentPanel provider={selected} kind="cnpj" canWrite={canWrite} isPending={uploadProviderCnpjCard.isPending} onUpload={(file: File) => { const reader = new FileReader(); reader.onload = () => { const base64 = String(reader.result).split(",")[1]; if (base64) uploadProviderCnpjCard.mutate({ providerId: selected.id, originalName: file.name, mimeType: file.type as "application/pdf" | "image/jpeg" | "image/png" | "image/webp", dataBase64: base64 }); }; reader.readAsDataURL(file); }} /><ProviderDocumentPanel provider={selected} kind="manual" canWrite={canWrite} isPending={uploadProviderBrandManual.isPending} onUpload={(file: File) => { const reader = new FileReader(); reader.onload = () => { const base64 = String(reader.result).split(",")[1]; if (base64) uploadProviderBrandManual.mutate({ providerId: selected.id, originalName: file.name, mimeType: file.type as "application/pdf" | "image/jpeg" | "image/png" | "image/webp", dataBase64: base64 }); }; reader.readAsDataURL(file); }} /></div></> : null}
      {entity.kind === "store" && editing ? <StorePhotoPanel store={selected} canWrite={canWrite} isPending={uploadStorePhoto.isPending} onUpload={(file: File) => { const reader = new FileReader(); reader.onload = () => { const base64 = String(reader.result).split(",")[1]; if (base64) uploadStorePhoto.mutate({ storeId: selected.id, originalName: file.name, mimeType: file.type as "image/jpeg" | "image/png" | "image/webp", dataBase64: base64 }); }; reader.readAsDataURL(file); }} /> : null}
      {entity.kind === "supplier" ? <SupplierPhotoPanel supplier={selected} canWrite={canWrite} isPending={uploadSupplierPhoto.isPending} onUpload={(file: File) => { const reader = new FileReader(); reader.onload = () => { const base64 = String(reader.result).split(",")[1]; if (base64) uploadSupplierPhoto.mutate({ supplierId: selected.id, originalName: file.name, mimeType: file.type as "image/jpeg" | "image/png" | "image/webp", dataBase64: base64 }); }; reader.readAsDataURL(file); }} /> : null}
      {entity.kind === "store" && editing ? <StoreSupervisorsPanel supervisors={supervisors} linkedSupervisors={storeSupervisors} canWrite={canWrite} isPending={setSupervisorStores.isPending} onToggle={toggleStoreSupervisor} /> : null}
      {entity.kind === "supplier" ? <SupplierDetailsPanel supplier={selected} cities={cities} serviceTypes={serviceTypes} mediaTypes={mediaTypes} offerings={supplierOfferings} coverage={supplierCoverage.data} footprint={operationalFootprint} /> : null}
      {relationCards.length ? <section><h2 className="font-display text-xl font-semibold text-foreground">Vínculos e cobertura</h2><p className="mt-1 text-sm text-muted-foreground">Selecione um cartão para consultar os registros vinculados sem sair desta ficha.</p><div className="mt-3 grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{relationCards.map(card => <button key={card.label} onClick={() => setExpandedRelation(current => current === card.label ? null : card.label)} className={`rounded-xl border bg-card p-4 text-left transition hover:border-primary/40 ${expandedRelation === card.label ? "border-primary ring-2 ring-primary/10" : "border-border"}`}><p className="text-2xl font-semibold text-primary">{card.count}</p><p className="mt-1 text-sm font-semibold text-foreground">{card.label}</p><p className="mt-1 text-xs text-muted-foreground">{card.description}</p></button>)}</div>{expandedRelation ? <ExpandedRelationPanel label={expandedRelation} rows={relationCards.find(card => card.label === expandedRelation)?.items ?? []} destination={relationCards.find(card => card.label === expandedRelation)?.path ?? `/cadastros/${registryGroups[entity.kind] ?? "territorio"}`} onOpen={(id: number) => { const card = relationCards.find(item => item.label === expandedRelation); if (card) setLocation(`${card.path}/${id}`); }} onViewAll={() => { const card = relationCards.find(item => item.label === expandedRelation); if (card) setLocation(card.path); }} /> : null}</section> : null}
    </section>}
  </div>;
}

function DetailOverview({ entity, record }: { entity: EntityConfig; record: RegistryRecord }) {
  const phoneUrl = whatsappUrl(record.phone as string | null | undefined);
  const websiteUrl = typeof record.website === "string" && record.website.trim() ? record.website : null;
  const entries = Object.entries({ "Status": record.active === false ? "Inativo" : "Ativo", "Código": record.code, "CNPJ": record.billingCnpj ?? record.document, "Contato": record.contactName, "E-mail": record.email, "Site": websiteUrl, "Telefone": record.phone, "Serviço principal": record.mainService, "Endereço": record.address, "Ponto de referência": record.referencePoint, "CEP": record.zipCode, "Horário de funcionamento": typeof record.openingHours === "string" ? formatStoreHours(record.openingHours) : record.openingHours, "UF": record.state, "IBGE": record.ibgeCode, "Observações": record.locationNotes ?? record.description }).filter(([, value]) => value);
  return <Card><CardContent className="p-6"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-semibold uppercase tracking-[0.14em] text-primary">Informações do cadastro</p><h2 className="mt-1 font-display text-2xl font-semibold">{recordName(record)}</h2></div><Badge variant="outline" className={record.active === false ? "text-muted-foreground" : "border-primary/30 bg-primary/10 text-primary"}>{record.active === false ? "Inativo" : "Ativo"}</Badge></div><div className="mt-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{entries.map(([label, value]) => <div key={label} className="rounded-xl bg-muted/50 p-3"><p className="text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">{label}</p><p className="mt-1 break-words text-sm text-foreground">{String(value)}</p></div>)}</div>{phoneUrl ? <a className="mt-5 inline-flex items-center text-sm font-semibold text-primary hover:underline" href={phoneUrl} target="_blank" rel="noreferrer">Conversar pelo WhatsApp <ExternalLink className="ml-1.5 h-3.5 w-3.5" /></a> : null}{entity.kind === "provider" && websiteUrl ? <a className="mt-3 inline-flex items-center text-sm font-semibold text-primary hover:underline" href={websiteUrl} target="_blank" rel="noreferrer">Abrir site da empresa <ExternalLink className="ml-1.5 h-3.5 w-3.5" /></a> : null}</CardContent></Card>;
}

function StoreSupervisorsPanel({ supervisors, linkedSupervisors, canWrite, isPending, onToggle }: { supervisors: RegistryRecord[]; linkedSupervisors: RegistryRecord[]; canWrite: boolean; isPending: boolean; onToggle: (supervisorId: number) => void }) {
  const linkedIds = new Set(linkedSupervisors.map(supervisor => supervisor.id));
  return <Card><CardContent className="p-6"><div className="flex flex-col gap-2 sm:flex-row sm:items-start sm:justify-between"><div><p className="text-xs font-semibold uppercase tracking-[0.14em] text-primary">Cobertura comercial</p><h2 className="mt-1 font-display text-xl font-semibold text-foreground">Supervisores vinculados</h2><p className="mt-1 text-sm leading-6 text-muted-foreground">Uma loja pode estar sob a responsabilidade de mais de um supervisor comercial.</p></div><Badge variant="outline" className="w-fit border-primary/30 bg-primary/10 text-primary">{linkedSupervisors.length} vinculados</Badge></div>{supervisors.length ? <div className="mt-5 grid gap-3 sm:grid-cols-2">{supervisors.map(supervisor => { const linked = linkedIds.has(supervisor.id); return <div key={supervisor.id} className={`flex items-center justify-between gap-3 rounded-xl border p-3 ${linked ? "border-primary/30 bg-primary/5" : "border-border bg-muted/30"}`}><div className="min-w-0"><p className="truncate text-sm font-semibold text-foreground">{recordName(supervisor)}</p><p className="mt-0.5 truncate text-xs text-muted-foreground">{String(supervisor.email ?? supervisor.phone ?? "Sem contato informado")}</p></div>{canWrite ? <Button type="button" variant={linked ? "outline" : "secondary"} size="sm" disabled={isPending} onClick={() => onToggle(supervisor.id)}>{linked ? "Desvincular" : "Vincular"}</Button> : <Badge variant="outline">{linked ? "Vinculado" : "Não vinculado"}</Badge>}</div>; })}</div> : <p className="mt-5 rounded-xl border border-dashed border-border p-4 text-sm text-muted-foreground">Nenhum supervisor comercial foi cadastrado ainda.</p>}</CardContent></Card>;
}

function ProviderLogoPanel({ provider, canWrite, isPending, onUpload }: { provider: RegistryRecord; canWrite: boolean; isPending: boolean; onUpload: (file: File) => void }) {
  const logoUrl = typeof provider.logoUrl === "string" ? provider.logoUrl : null;
  return <Card><CardContent className="flex flex-col gap-5 p-6 sm:flex-row sm:items-center"><div className="grid h-28 w-40 shrink-0 place-items-center overflow-hidden rounded-xl border border-border bg-muted/50"><input id="provider-logo-upload" type="file" accept="image/jpeg,image/png,image/webp" className="sr-only" disabled={!canWrite || isPending} onChange={event => { const file = event.target.files?.[0]; if (!file) return; if (file.size > 3 * 1024 * 1024) { toast.error("O logotipo deve ter até 3 MB."); return; } onUpload(file); event.currentTarget.value = ""; }} />{logoUrl ? <img src={logoUrl} alt={`Logotipo de ${recordName(provider)}`} className="h-full w-full object-contain p-2" /> : <ImageIcon className="h-8 w-8 text-muted-foreground" />}</div><div className="min-w-0 flex-1"><p className="text-xs font-semibold uppercase tracking-[0.14em] text-primary">Identidade da empresa</p><h2 className="mt-1 font-display text-lg font-semibold text-foreground">Logotipo</h2><p className="mt-1 text-sm text-muted-foreground">Envie PNG, JPG ou WEBP de até 3 MB. A imagem é exibida sem corte na ficha empresarial.</p>{canWrite ? <label htmlFor="provider-logo-upload"><Button type="button" asChild disabled={isPending} className="mt-4 bg-primary"><span><Upload className="mr-2 h-4 w-4" />{isPending ? "Enviando…" : logoUrl ? "Substituir logotipo" : "Adicionar logotipo"}</span></Button></label> : null}</div></CardContent></Card>;
}

function ProviderDocumentPanel({ provider, kind, canWrite, isPending, onUpload }: { provider: RegistryRecord; kind: "cnpj" | "manual"; canWrite: boolean; isPending: boolean; onUpload: (file: File) => void }) {
  const isCnpj = kind === "cnpj";
  const label = isCnpj ? "Cartão CNPJ" : "Manual da marca";
  const url = typeof provider[isCnpj ? "cnpjCardUrl" : "brandManualUrl"] === "string" ? String(provider[isCnpj ? "cnpjCardUrl" : "brandManualUrl"]) : null;
  const inputId = `provider-${kind}-upload`;
  return <Card><CardContent className="p-5"><input id={inputId} type="file" accept="application/pdf,image/jpeg,image/png,image/webp" className="sr-only" disabled={!canWrite || isPending} onChange={event => { const file = event.target.files?.[0]; if (!file) return; const limit = isCnpj ? 5 : 10; if (file.size > limit * 1024 * 1024) { toast.error(`${label} deve ter até ${limit} MB.`); return; } onUpload(file); event.currentTarget.value = ""; }} /><p className="text-xs font-semibold uppercase tracking-[0.14em] text-primary">Documento institucional</p><h2 className="mt-1 font-display text-lg font-semibold text-foreground">{label}</h2><p className="mt-2 min-h-10 text-sm text-muted-foreground">{url ? "Documento disponível para consulta." : "Anexe um PDF ou imagem para centralizar esta informação institucional."}</p><div className="mt-4 flex flex-wrap gap-2">{url ? <Button type="button" variant="outline" size="sm" asChild><a href={url} target="_blank" rel="noreferrer"><ExternalLink className="mr-2 h-3.5 w-3.5" />Abrir</a></Button> : null}{canWrite ? <label htmlFor={inputId}><Button type="button" size="sm" asChild disabled={isPending} className="bg-primary"><span><Upload className="mr-2 h-3.5 w-3.5" />{isPending ? "Enviando…" : url ? "Substituir" : "Anexar"}</span></Button></label> : null}</div></CardContent></Card>;
}

function StorePhotoPanel({ store, canWrite, isPending, onUpload }: { store: RegistryRecord; canWrite: boolean; isPending: boolean; onUpload: (file: File) => void }) {
  const photoUrl = typeof store.photoUrl === "string" ? store.photoUrl : null;
  return <Card><CardContent className="flex flex-col gap-5 p-6 sm:flex-row sm:items-center"><div className="grid h-28 w-40 shrink-0 place-items-center overflow-hidden rounded-xl border border-border bg-muted/50"><input id="store-photo-upload" type="file" accept="image/jpeg,image/png,image/webp" className="sr-only" disabled={!canWrite || isPending} onChange={event => { const file = event.target.files?.[0]; if (!file) return; if (file.size > 5 * 1024 * 1024) { toast.error("A foto da loja deve ter até 5 MB."); return; } onUpload(file); event.currentTarget.value = ""; }} />{photoUrl ? <img src={photoUrl} alt={`Foto de ${recordName(store)}`} className="h-full w-full object-cover" /> : <ImageIcon className="h-8 w-8 text-muted-foreground" />}</div><div className="min-w-0 flex-1"><p className="text-xs font-semibold uppercase tracking-[0.14em] text-primary">Identificação da unidade</p><h2 className="mt-1 font-display text-lg font-semibold text-foreground">Foto da loja</h2><p className="mt-1 text-sm text-muted-foreground">Envie PNG, JPG ou WEBP de até 5 MB. A imagem ajuda a reconhecer a unidade em seus vínculos operacionais.</p>{canWrite ? <label htmlFor="store-photo-upload"><Button type="button" asChild disabled={isPending} className="mt-4 bg-primary"><span><Upload className="mr-2 h-4 w-4" />{isPending ? "Enviando…" : photoUrl ? "Substituir foto" : "Adicionar foto"}</span></Button></label> : null}</div></CardContent></Card>;
}

type SupplierCoverage = { citiesBySupplier: Array<{ supplierId: number; cityId: number }>; servicesBySupplier: Array<{ supplierId: number; serviceTypeId: number }>; mediaBySupplier: Array<{ supplierId: number; mediaTypeId: number }> };
type SupplierOperationalFootprint = { actions?: Array<{ id: number; name: string; cityId: number }>; events?: Array<{ id: number; name: string; cityId: number }>; mediaPoints?: Array<{ id: number; name: string; cityId: number; supplierId: number | null }>; actionSuppliers?: Array<{ actionId: number; supplierId: number }>; eventSuppliers?: Array<{ eventId: number; supplierId: number }> };

function SupplierPhotoPanel({ supplier, canWrite, isPending, onUpload }: { supplier: RegistryRecord; canWrite: boolean; isPending: boolean; onUpload: (file: File) => void }) {
  const photoUrl = typeof supplier.photoUrl === "string" ? supplier.photoUrl : null;
  return <Card><CardContent className="flex flex-col gap-5 p-6 sm:flex-row sm:items-center"><div className="grid h-28 w-28 shrink-0 place-items-center overflow-hidden rounded-xl border border-border bg-muted/50"><input id="supplier-photo-upload" type="file" accept="image/jpeg,image/png,image/webp" className="sr-only" disabled={!canWrite || isPending} onChange={event => { const file = event.target.files?.[0]; if (!file) return; if (file.size > 3 * 1024 * 1024) { toast.error("A foto deve ter até 3 MB."); return; } onUpload(file); event.currentTarget.value = ""; }} />{photoUrl ? <img src={photoUrl} alt={`Foto de ${recordName(supplier)}`} className="h-full w-full object-cover" /> : <ImageIcon className="h-8 w-8 text-muted-foreground" />}</div><div className="min-w-0 flex-1"><p className="text-xs font-semibold uppercase tracking-[0.14em] text-primary">Identificação visual</p><h2 className="mt-1 font-display text-xl font-semibold text-foreground">Foto do fornecedor</h2><p className="mt-1 text-sm leading-6 text-muted-foreground">Esta foto será usada nos fornecedores envolvidos nas fichas de Ações.</p>{canWrite ? <label htmlFor="supplier-photo-upload" className="mt-4 inline-flex w-fit cursor-pointer items-center rounded-lg border border-border px-3 py-2 text-sm font-semibold text-foreground transition hover:bg-secondary"><Upload className="mr-2 h-4 w-4" />{isPending ? "Enviando…" : photoUrl ? "Trocar foto" : "Adicionar foto"}</label> : null}</div></CardContent></Card>;
}

function SupplierDetailsPanel({ supplier, cities, serviceTypes, mediaTypes, offerings, coverage, footprint }: { supplier: RegistryRecord; cities: RegistryRecord[]; serviceTypes: RegistryRecord[]; mediaTypes: RegistryRecord[]; offerings: RegistryRecord[]; coverage?: SupplierCoverage; footprint: SupplierOperationalFootprint }) {
  const cityIds = new Set((coverage?.citiesBySupplier ?? []).filter(item => item.supplierId === supplier.id).map(item => item.cityId));
  if (supplier.cityId) cityIds.add(Number(supplier.cityId));
  const serviceIds = new Set((coverage?.servicesBySupplier ?? []).filter(item => item.supplierId === supplier.id).map(item => item.serviceTypeId));
  const mediaIds = new Set((coverage?.mediaBySupplier ?? []).filter(item => item.supplierId === supplier.id).map(item => item.mediaTypeId));
  const supplierOffers = offerings.filter(item => Number(item.supplierId) === supplier.id);
  const averageCost = supplierOffers.length ? supplierOffers.reduce((total, item) => total + Number(item.unitPrice ?? 0), 0) / supplierOffers.length : 0;
  const actionIds = new Set((footprint.actionSuppliers ?? []).filter(item => item.supplierId === supplier.id).map(item => item.actionId));
  const eventIds = new Set((footprint.eventSuppliers ?? []).filter(item => item.supplierId === supplier.id).map(item => item.eventId));
  const actions = (footprint.actions ?? []).filter(item => actionIds.has(item.id));
  const events = (footprint.events ?? []).filter(item => eventIds.has(item.id));
  const mediaPoints = (footprint.mediaPoints ?? []).filter(item => item.supplierId === supplier.id);
  const linkedCities = cities.filter(item => cityIds.has(item.id));
  const linkedServices = serviceTypes.filter(item => serviceIds.has(item.id));
  const linkedMedia = mediaTypes.filter(item => mediaIds.has(item.id));
  const money = (value: unknown) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(Number(value ?? 0));
  const names = (items: RegistryRecord[], empty = 'Não informado') => items.length ? items.map(recordName).join(', ') : empty;
  const paymentType = supplier.partnershipType === 'barter' ? 'Permuta' : supplier.partnershipType === 'mixed' ? 'Misto' : 'Pago';
  return <section className="grid gap-5 xl:grid-cols-[minmax(0,1.3fr)_minmax(300px,.7fr)]">
    <div className="space-y-5">
      <Card><CardContent className="p-6"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-semibold uppercase tracking-[0.14em] text-primary">Dados do fornecedor</p><h2 className="mt-1 font-display text-2xl font-semibold text-foreground">Identificação e contrato</h2><p className="mt-1 text-sm leading-6 text-muted-foreground">Visão relacional do fornecedor</p><p className="mt-1 text-sm leading-6 text-muted-foreground">Todos os dados cadastrados no fluxo de cinco etapas.</p></div><Badge variant="outline" className={supplier.active === false ? 'text-muted-foreground' : 'border-primary/30 bg-primary/10 text-primary'}>{supplier.active === false ? 'Inativo' : 'Ativo'}</Badge></div><div className="mt-6 grid gap-3 sm:grid-cols-2"><RelationInfo title="Nome" value={recordName(supplier)} /><RelationInfo title="Razão social" value={String(supplier.legalName ?? 'Não informado')} /><RelationInfo title="CNPJ" value={String(supplier.document ?? 'Não informado')} /><RelationInfo title="Endereço" value={String(supplier.address ?? 'Não informado')} /><RelationInfo title="Contrato" value={supplier.hasContract ? 'Contrato cadastrado' : 'Sem contrato informado'} /><RelationInfo title="Período do contrato" value={supplier.contractStartDate || supplier.contractEndDate ? `${String(supplier.contractStartDate ?? 'Início não informado')} até ${String(supplier.contractEndDate ?? 'Fim não informado')}` : 'Não informado'} /></div></CardContent></Card>
      <Card><CardContent className="p-6"><p className="text-xs font-semibold uppercase tracking-[0.14em] text-primary">Dados de pagamento</p><h2 className="mt-1 font-display text-xl font-semibold text-foreground">Condições comerciais</h2><div className="mt-5 grid gap-3 sm:grid-cols-2"><RelationInfo title="Tipo de pagamento" value={paymentType} /><RelationInfo title="Dia de pagamento" value={String(supplier.paymentDay ?? supplier.paymentRecurrence ?? 'Não informado')} /><RelationInfo title="Forma de pagamento" value={String(supplier.paymentMethod ?? 'Não informado')} /><RelationInfo title="Valor da permuta" value={supplier.barterValue ? money(supplier.barterValue) : 'Não informado'} /><RelationInfo title="Serviço oferecido na permuta" value={String(supplier.barterService ?? 'Não informado')} /><RelationInfo title="Observações" value={String(supplier.paymentNotes ?? 'Não informado')} /></div></CardContent></Card>
      <Card><CardContent className="p-6"><p className="text-xs font-semibold uppercase tracking-[0.14em] text-primary">Serviços e produtos</p><h2 className="mt-1 font-display text-xl font-semibold text-foreground">Oferta comercial cadastrada</h2><div className="mt-5 grid gap-3 md:grid-cols-2"><RelationInfo title="Serviços vinculados" value={names(linkedServices)} /><RelationInfo title="Tipos de mídia" value={names(linkedMedia)} /><RelationInfo title="Ofertas" value={supplierOffers.length ? supplierOffers.map(item => `${recordName(item)} — ${money(item.unitPrice)}${item.averageUnitPrice ? ` · médio ${money(item.averageUnitPrice)}` : ''}`).join(' | ') : 'Nenhuma oferta cadastrada'} /><RelationInfo title="Custo médio das ofertas" value={money(averageCost)} /></div></CardContent></Card>
    </div>
    <aside className="space-y-5"><Card><CardContent className="p-5"><p className="text-xs font-semibold uppercase tracking-[0.14em] text-primary">Responsável</p><h2 className="mt-1 font-display text-xl font-semibold text-foreground">Representante</h2><div className="mt-5 space-y-3"><RelationInfo title="Nome" value={String(supplier.contactName ?? 'Não informado')} /><RelationInfo title="Telefone" value={String(supplier.phone ?? 'Não informado')} /><RelationInfo title="E-mail" value={String(supplier.email ?? 'Não informado')} /></div></CardContent></Card><Card><CardContent className="p-5"><p className="text-xs font-semibold uppercase tracking-[0.14em] text-primary">Localidade</p><h2 className="mt-1 font-display text-xl font-semibold text-foreground">Atendimento</h2><div className="mt-5 space-y-3"><RelationInfo title="Cidade base" value={String(cities.find(item => item.id === Number(supplier.cityId)) ? recordName(cities.find(item => item.id === Number(supplier.cityId))!) : 'Não informado')} /><RelationInfo title="Cidades atendidas" value={names(linkedCities)} /></div></CardContent></Card><Card><CardContent className="p-5"><p className="text-xs font-semibold uppercase tracking-[0.14em] text-primary">Relacionamentos</p><h2 className="mt-1 font-display text-xl font-semibold text-foreground">Uso operacional</h2><div className="mt-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-1"><RelationInfo title="Ações" value={names(actions)} /><RelationInfo title="Eventos" value={names(events)} /><RelationInfo title="Pontos de mídia" value={mediaPoints.length ? `${mediaPoints.length} ponto(s) vinculado(s)` : 'Nenhum ponto vinculado'} /></div></CardContent></Card></aside>
  </section>;
}

function RelationInfo({ title, value }: { title: string; value: string }) { return <div className="rounded-xl border border-border bg-muted/40 p-4"><p className="text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">{title}</p><p className="mt-2 text-sm leading-6 text-foreground">{value}</p></div>; }

function RegistryEditor({ kind, form, setForm, providers, regionals, cities, mediaTypes, serviceTypes, onSave, saving }: { kind: string; form: Record<string, string>; setForm: (value: Record<string, string>) => void; providers: RegistryRecord[]; regionals: RegistryRecord[]; cities: RegistryRecord[]; mediaTypes: RegistryRecord[]; serviceTypes: RegistryRecord[]; onSave: () => void; saving: boolean }) {
  const field = (key: string, label: string, type = "text") => <label className="grid gap-2 text-sm font-medium"><span>{label}</span><Input type={type} value={form[key] ?? ""} onChange={event => setForm({ ...form, [key]: event.target.value })} /></label>;
  const citySelect = <label className="grid gap-2 text-sm font-medium"><span>Cidade</span><select value={form.cityId ?? ""} onChange={event => setForm({ ...form, cityId: event.target.value })} className="h-10 rounded-md border border-input bg-background px-3 text-sm"><option value="">Sem cidade vinculada</option>{cities.map(city => <option key={city.id} value={city.id}>{recordName(city)}</option>)}</select></label>;
  const partnershipFields = <><label className="grid gap-2 text-sm font-medium"><span>Modalidade</span><select value={form.partnershipType ?? "paid"} onChange={event => setForm({ ...form, partnershipType: event.target.value })} className="h-10 rounded-md border border-input bg-background px-3 text-sm"><option value="paid">Pago</option><option value="barter">Permuta</option><option value="mixed">Misto</option></select></label>{field("paymentMethod", "Forma de pagamento")}{field("paymentRecurrence", "Recorrência")}<label className="grid gap-2 text-sm font-medium"><span>Possui contrato?</span><select value={form.hasContract ?? "no"} onChange={event => setForm({ ...form, hasContract: event.target.value })} className="h-10 rounded-md border border-input bg-background px-3 text-sm"><option value="yes">Sim</option><option value="no">Não</option></select></label></>;
  const mediaParents = mediaTypes.filter(type => !type.parentMediaTypeId && String(type.operationCategory ?? "graphics") === form.operationCategory);
  const providerRegionalIds = new Set(regionals.filter(regional => regional.providerId === Number(form.providerRecordId)).map(regional => regional.id));
  const providerCities = cities.filter(city => providerRegionalIds.has(Number(city.regionalId)));
  return <Card><CardContent className="p-6"><div className="grid gap-4 md:grid-cols-2">{field("name", kind === "provider" ? "Nome da empresa" : kind === "supplier" ? "Nome de exibição" : "Nome")}{kind === "provider" ? <>{field("legalName", "Razão social")}{field("billingCnpj", "CNPJ de faturamento")}{field("contactName", "Nome do contato")}{field("phone", "Telefone")}{field("email", "E-mail", "email")}{field("website", "Site", "url")}<label className="grid gap-2 text-sm font-medium md:col-span-2"><span>Endereço de faturamento</span><Input value={form.address ?? ""} onChange={event => setForm({ ...form, address: event.target.value })} /></label><label className="grid gap-2 text-sm font-medium"><span>Cidade-matriz</span><select value={form.headquartersCityId ?? ""} onChange={event => setForm({ ...form, headquartersCityId: event.target.value })} className="h-10 rounded-md border border-input bg-background px-3 text-sm"><option value="">Não definida</option>{providerCities.map(city => <option key={city.id} value={city.id}>{recordName(city)} · {String(city.state ?? "MG")}</option>)}</select></label><label className="grid gap-2 text-sm font-medium"><span>Cores da empresa</span><Input value={form.brandColors ?? ""} onChange={event => setForm({ ...form, brandColors: event.target.value })} placeholder="#0E723B, #F45103" /><span className="text-xs font-normal text-muted-foreground">Separe as cores hexadecimais por vírgula.</span></label></> : null}{kind === "regional" ? <><label className="grid gap-2 text-sm font-medium"><span>Código</span><Input value={form.code ?? ""} onChange={event => setForm({ ...form, code: event.target.value.toUpperCase() })} /></label><label className="grid gap-2 text-sm font-medium"><span>Empresa responsável</span><select value={form.providerId ?? ""} onChange={event => setForm({ ...form, providerId: event.target.value })} className="h-10 rounded-md border border-input bg-background px-3 text-sm"><option value="">Sem empresa vinculada</option>{providers.map(provider => <option key={provider.id} value={provider.id}>{recordName(provider)}</option>)}</select></label></> : null}{kind === "city" ? <><label className="grid gap-2 text-sm font-medium"><span>Regional</span><select value={form.regionalId ?? ""} onChange={event => setForm({ ...form, regionalId: event.target.value })} className="h-10 rounded-md border border-input bg-background px-3 text-sm">{regionals.map(regional => <option key={regional.id} value={regional.id}>{recordName(regional)}</option>)}</select></label>{field("state", "UF")}{field("ibgeCode", "Código IBGE")}{field("zipCode", "CEP")}{field("address", "Endereço")}{field("latitude", "Latitude", "number")}{field("longitude", "Longitude", "number")}{field("locationNotes", "Observações de localização")}</> : null}{kind === "store" ? <><label className="grid gap-2 text-sm font-medium"><span>Cidade</span><select value={form.cityId ?? ""} onChange={event => setForm({ ...form, cityId: event.target.value })} className="h-10 rounded-md border border-input bg-background px-3 text-sm">{cities.map(city => <option key={city.id} value={city.id}>{recordName(city)}</option>)}</select></label>{field("code", "Código")}{field("address", "Endereço")}{field("referencePoint", "Ponto de referência")}{field("zipCode", "CEP")}{field("phone", "Telefone")}{field("email", "E-mail", "email")}<StoreHoursField value={form.openingHours ?? ""} onChange={openingHours => setForm({ ...form, openingHours })} /><CoordinatesField latitude={form.latitude ?? ""} longitude={form.longitude ?? ""} setLatitude={latitude => setForm({ ...form, latitude })} setLongitude={longitude => setForm({ ...form, longitude })} /></> : null}{kind === "supplier" ? <>{field("legalName", "Razão social")}{field("document", "CNPJ")}{field("contactName", "Contato")}{field("phone", "Telefone")}{field("email", "E-mail", "email")}<label className="grid gap-2 text-sm font-medium"><span>Especialidade</span><select value={form.mainService ?? ""} onChange={event => setForm({ ...form, mainService: event.target.value })} className="h-10 rounded-md border border-input bg-background px-3 text-sm"><option value="">Selecione um serviço</option>{serviceTypes.filter(item => item.active !== false).map(service => <option key={service.id} value={recordName(service)}>{recordName(service)}</option>)}</select></label>{citySelect}{partnershipFields}</> : null}{kind === "partner" ? <>{field("email", "E-mail", "email")}{field("phone", "Telefone")}{citySelect}{partnershipFields}</> : null}{kind === "supervisor" ? <>{field("email", "E-mail", "email")}{field("phone", "Telefone")}</> : null}{kind === "media" ? <><label className="grid gap-2 text-sm font-medium"><span>Tipo principal</span><select value={form.operationCategory ?? "graphics"} onChange={event => setForm({ ...form, operationCategory: event.target.value, parentMediaTypeId: "" })} className="h-10 rounded-md border border-input bg-background px-3 text-sm"><option value="graphics">Mídia Urbana</option><option value="audio_video">Mídia Tradicional</option><option value="leafleting">Panfletagem</option><option value="sound_car">Carro de Som</option><option value="influencers">Influencers</option></select></label><label className="grid gap-2 text-sm font-medium"><span>Subtipo pai</span><select value={form.parentMediaTypeId ?? ""} onChange={event => setForm({ ...form, parentMediaTypeId: event.target.value })} className="h-10 rounded-md border border-input bg-background px-3 text-sm"><option value="">Este registro é um subtipo principal</option>{mediaParents.map(type => <option key={type.id} value={type.id}>{recordName(type)}</option>)}</select></label></> : null}{kind === "financial_category" ? <label className="grid gap-2 text-sm font-medium md:col-span-2"><span>Descrição</span><Input value={form.description ?? ""} onChange={event => setForm({ ...form, description: event.target.value })} /></label> : null}</div><div className="mt-6 flex justify-end"><Button disabled={saving || !form.name?.trim()} onClick={onSave} className="bg-primary text-primary-foreground">{saving ? "Salvando…" : "Salvar alterações"}</Button></div></CardContent></Card>;
}

function summary(kind: string, row: RegistryRecord, lookup: { providers: RegistryRecord[]; regionals: RegistryRecord[]; cities: RegistryRecord[] }) { if (kind === "regional") { const provider = lookup.providers.find(item => item.id === Number(row.providerId)); return `${row.code ?? "Sem código"} · ${provider ? recordName(provider) : "Sem empresa vinculada"}`; } if (kind === "city") { const regional = lookup.regionals.find(item => item.id === Number(row.regionalId)); return `${row.state ?? ""} · ${regional ? recordName(regional) : "Sem regional vinculada"}`; } return String(row.email ?? row.phone ?? row.code ?? row.description ?? "Abrir detalhes do cadastro"); }
function getRelations(kind: string, record: RegistryRecord, all: { providers: RegistryRecord[]; regionals: RegistryRecord[]; cities: RegistryRecord[]; stores: RegistryRecord[]; suppliers: RegistryRecord[] }) { const companyRegionals = all.regionals.filter(item => Number(item.providerId) === record.id); const regionalCities = all.cities.filter(item => Number(item.regionalId) === record.id); const scopeCities = kind === "provider" ? all.cities.filter(city => companyRegionals.some(regional => regional.id === Number(city.regionalId))) : kind === "regional" ? regionalCities : kind === "city" ? [record] : []; const scopeStores = all.stores.filter(store => scopeCities.some(city => city.id === Number(store.cityId))); const scopeSuppliers = all.suppliers.filter(supplier => scopeCities.some(city => city.id === Number(supplier.cityId))); if (kind === "provider") return [{ label: "Regionais", count: companyRegionals.length, description: "Estruturas atendidas", path: "/cadastros/regionais", items: companyRegionals }, { label: "Cidades", count: scopeCities.length, description: "Cidades da cobertura", path: "/cadastros/cidades", items: scopeCities }, { label: "Lojas", count: scopeStores.length, description: "Lojas vinculadas", path: "/cadastros/lojas", items: scopeStores }, { label: "Fornecedores", count: scopeSuppliers.length, description: "Fornecedores locais", path: "/cadastros/fornecedores", items: scopeSuppliers }]; if (["regional", "city"].includes(kind)) return [{ label: "Cidades", count: scopeCities.length, description: "Territórios vinculados", path: "/cadastros/cidades", items: scopeCities }, { label: "Lojas", count: scopeStores.length, description: "Lojas vinculadas", path: "/cadastros/lojas", items: scopeStores }, { label: "Fornecedores", count: scopeSuppliers.length, description: "Fornecedores locais", path: "/cadastros/fornecedores", items: scopeSuppliers }]; return []; }

function ExpandedRelationPanel({ label, rows, destination, onOpen, onViewAll }: { label: string; rows: RegistryRecord[]; destination: string; onOpen: (id: number) => void; onViewAll: () => void }) { return <Card className="mt-4 overflow-hidden"><CardContent className="p-0"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-5 py-4"><div><p className="font-display text-lg font-semibold text-foreground">{label} vinculados</p><p className="mt-1 text-xs text-muted-foreground">Consulte os registros relacionados a este cadastro.</p></div><Button type="button" variant="outline" size="sm" onClick={onViewAll}>Ver todos</Button></div>{rows.length ? <div className="divide-y divide-border">{rows.map(row => <button key={row.id} type="button" className="flex w-full items-center justify-between gap-3 px-5 py-3 text-left transition hover:bg-muted/50" onClick={() => onOpen(row.id)}><span className="min-w-0"><span className="block truncate text-sm font-medium text-foreground">{recordName(row)}</span><span className="mt-0.5 block truncate text-xs text-muted-foreground">{String(row.address ?? row.email ?? row.phone ?? row.code ?? "Cadastro vinculado")}</span></span><ChevronRight className="h-4 w-4 shrink-0 text-primary" /></button>)}</div> : <p className="p-5 text-sm text-muted-foreground">Não há {label.toLowerCase()} vinculados a este cadastro.</p>}</CardContent></Card>; }
